files.content:
:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --primary: #f4a261;
  --accent: #e76f51;
  --text: #f0e6d2;
  --bar-bg: #3a3a55;
  --hunger-color: #e63946;
  --happiness-color: #f4a261;
  --energy-color: #2a9d8f;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 400px;
  text-align: center;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 16px;
  color: var(--primary);
}

.pet {
  position: relative;
  width: 120px;
  height: 120px;
  margin: 0 auto 16px;
}

.pet-body {
  width: 100%;
  height: 100%;
  background: var(--primary);
  border-radius: 24px;
  box-shadow:
    inset -8px -8px 0 rgba(0,0,0,0.1),
    inset 8px 8px 0 rgba(255,255,255,0.1);
}

.pet-eye {
  position: absolute;
  top: 30%;
  width: 20px;
  height: 20px;
  background: var(--bg);
  border-radius: 50%;
}

.pet-eye.left {
  left: 25%;
}

.pet-eye.right {
  right: 25%;
}

.pet-mouth {
  position: absolute;
  bottom: 25%;
  left: 50%;
  transform: translateX(-50%);
  width: 40px;
  height: 20px;
  border-bottom: 4px solid var(--bg);
  border-radius: 0 0 40px 40px;
}

.mood {
  font-size: 1.1rem;
  margin-bottom: 20px;
  color: var(--primary);
  font-weight: 600;
}

.stats {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

.stat {
  text-align: left;
}

.stat-label {
  display: block;
  font-size: 0.9rem;
  margin-bottom: 4px;
  color: var(--text);
}

.bar {
  height: 16px;
  background: var(--bar-bg);
  border-radius: 8px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  border-radius: 8px;
  transition: width 0.3s ease;
}

.bar-fill.hunger {
  background: var(--hunger-color);
}

.bar-fill.happiness {
  background: var(--happiness-color);
}

.bar-fill.energy {
  background: var(--energy-color);
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

button {
  font-family: inherit;
  font-size: 1rem;
  padding: 12px 20px;
  border: none;
  border-radius: 8px;
  background: var(--primary);
  color: var(--bg);
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  flex: 1;
  min-width: 80px;
}

button:hover {
  background: var(--accent);
}

button:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

button:active {
  transform: scale(0.95);
}

@media (max-width: 360px) {
  .card {
    padding: 16px;
  }
  button {
    padding: 10px 12px;
    font-size: 0.9rem;
  }
}

const hungerFill = document.getElementById('hunger-fill');
const happinessFill = document.getElementById('happiness-fill');
const energyFill = document.getElementById('energy-fill');
const hungerBar = document.getElementById('hunger-bar');
const happinessBar = document.getElementById('happiness-bar');
const energyBar = document.getElementById('energy-bar');
const moodEl = document.getElementById('mood');

const state = {
  hunger: 80,
  happiness: 70,
  energy: 60
};

function clamp(v) {
  return Math.max(0, Math.min(100, v));
}

function updateUI() {
  hungerFill.style.width = state.hunger + '%';
  happinessFill.style.width = state.happiness + '%';
  energyFill.style.width = state.energy + '%';
  hungerBar.setAttribute('aria-valuenow', state.hunger);
  happinessBar.setAttribute('aria-valuenow', state.happiness);
  energyBar.setAttribute('aria-valuenow', state.energy);

  const avg = (state.hunger + state.happiness + state.energy) / 3;
  let mood;
  if (avg >= 70) mood = 'Happy';
  else if (avg >= 40) mood = 'Okay';
  else mood = 'Sad';
  moodEl.textContent = 'Mood: ' + mood;
}

function feed() {
  state.hunger = clamp(state.hunger + 15);
  state.energy = clamp(state.energy - 5);
  updateUI();
}

function play() {
  state.happiness = clamp(state.happiness + 15);
  state.energy = clamp(state.energy - 10);
  state.hunger = clamp(state.hunger - 10);
  updateUI();
}

function sleep() {
  state.energy = clamp(state.energy + 20);
  state.hunger = clamp(state.hunger - 5);
  updateUI();
}

document.getElementById('feed-btn').addEventListener('click', feed);
document.getElementById('play-btn').addEventListener('click', play);
document.getElementById('sleep-btn').addEventListener('click', sleep);

updateUI();
